import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import { 
  FaUser, FaEnvelope, FaCalendar, FaTrophy, FaFire, FaClock, 
  FaSignOutAlt, FaCamera, FaHeart, FaTrash, FaMars, FaVenus, 
  FaUpload, FaImage, FaEdit, FaSave, FaTimes, FaWeight, FaRuler, 
  FaBirthdayCake, FaBrain, FaMoon, FaApple, FaRunning, FaCoffee, 
  FaVenusMars, FaNotesMedical, FaBed, FaDumbbell, FaSmile, FaUserMd,
  FaCheckCircle, FaCalculator, FaInfoCircle, FaArrowUp, FaArrowDown
} from 'react-icons/fa';

function Profile() {
  const navigate = useNavigate();
  const [showAvatarPicker, setShowAvatarPicker] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [customImageUrl, setCustomImageUrl] = useState('');
  const [showUrlInput, setShowUrlInput] = useState(false);
  
  // Track which section is being edited
  const [editingSection, setEditingSection] = useState(null);
  
  // Height in feet and inches
  const [heightFeet, setHeightFeet] = useState('');
  const [heightInches, setHeightInches] = useState('');
 
  
  // User Information State
  const [userInfo, setUserInfo] = useState({
    // Basic Info
    name: '',
    email: '',
    age: '',
    birthday: '',
    gender: '',
    
    // Physical Info (weight in kg, height stored as inches)
    height: '', // stored as total inches
    weight: '',
    
    // Mental Health Info
    primaryConcern: '',
    sleepHours: '',
    exerciseFrequency: '',
    stressLevel: '',
    moodPattern: '',
    therapyHistory: '',
    medications: '',
    
    // Lifestyle
    dailyRoutine: '',
    waterIntake: '',
    caffeineIntake: '',
    socialTime: '',
    
    // Goals
    mentalHealthGoals: '',
    
    // Metadata
    joined: '',
    avatar: null,
    avatarCategory: null
  });

  const [tempInfo, setTempInfo] = useState({});
  const [tempHeightFeet, setTempHeightFeet] = useState('');
  const [tempHeightInches, setTempHeightInches] = useState('');

  // Refs for scrolling
  const sectionRefs = {
    personal: useRef(null),
    physical: useRef(null),
    mental: useRef(null),
    lifestyle: useRef(null),
    goals: useRef(null),
  };

  // Avatar arrays
  const boyAvatars = [
    { id: 1, url: 'https://randomuser.me/api/portraits/men/1.jpg', name: 'Alex' },
    { id: 2, url: 'https://randomuser.me/api/portraits/men/2.jpg', name: 'Ben' },
    { id: 3, url: 'https://randomuser.me/api/portraits/men/3.jpg', name: 'Charlie' },
    { id: 4, url: 'https://randomuser.me/api/portraits/men/4.jpg', name: 'David' },
    { id: 5, url: 'https://randomuser.me/api/portraits/men/5.jpg', name: 'Ethan' },
    { id: 6, url: 'https://randomuser.me/api/portraits/men/6.jpg', name: 'Frank' },
  ];

  const girlAvatars = [
    { id: 1, url: 'https://randomuser.me/api/portraits/women/1.jpg', name: 'Emma' },
    { id: 2, url: 'https://randomuser.me/api/portraits/women/2.jpg', name: 'Sophia' },
    { id: 3, url: 'https://randomuser.me/api/portraits/women/3.jpg', name: 'Olivia' },
    { id: 4, url: 'https://randomuser.me/api/portraits/women/4.jpg', name: 'Ava' },
    { id: 5, url: 'https://randomuser.me/api/portraits/women/5.jpg', name: 'Mia' },
    { id: 6, url: 'https://randomuser.me/api/portraits/women/6.jpg', name: 'Isabella' },
  ];

  const customAvatars = [
    { id: 1, url: 'https://i.pinimg.com/736x/a1/27/73/a1277303ec49ee936b2ba11bb3a98a18.jpg', name: 'Cartoon 1', category: 'cartoon' },
    { id: 2, url: 'https://i1-c.pinimg.com/1200x/67/ef/9d/67ef9d9bb1b009281379840a737c811f.jpg', name: 'Cartoon 2', category: 'cartoon' },
  ];

  // Options for dropdowns
  const concerns = [
    'Anxiety', 'Depression', 'Stress Management', 'Sleep Issues', 
    'Self-esteem', 'Relationship Issues', 'Work-Life Balance', 'Burnout'
  ];
  
  const stressLevels = ['Low', 'Mild', 'Moderate', 'High', 'Very High'];
  const exerciseOptions = ['Daily', '3-5 times/week', '1-2 times/week', 'Rarely', 'Never'];
  const moodPatterns = ['Morning Person', 'Night Owl', 'Irregular', 'Consistent'];


  // Convert inches to feet/inches
  const inchesToFeetInches = (totalInches) => {
    if (!totalInches) return { feet: '', inches: '' };
    const feet = Math.floor(totalInches / 12);
    const inches = totalInches % 12;
    return { feet, inches };
  };

  // Convert feet/inches to inches
  const feetInchesToInches = (feet, inches) => {
    return (parseInt(feet) || 0) * 12 + (parseInt(inches) || 0);
  };

  useEffect(() => {
    // Load saved data
    const savedAvatar = localStorage.getItem('userAvatar');
    const savedCategory = localStorage.getItem('userAvatarCategory');
    const savedUserInfo = localStorage.getItem('userInfo');
    
    const defaultInfo = {
      name: localStorage.getItem('userName') || 'User',
      email: localStorage.getItem('userEmail') || 'user@example.com',
      joined: new Date().toLocaleDateString(),
      avatar: savedAvatar,
      avatarCategory: savedCategory,
      age: '',
      birthday: '',
      gender: '',
      height: '',
      weight: '',
      primaryConcern: '',
      sleepHours: '',
      exerciseFrequency: '',
      stressLevel: '',
      moodPattern: '',
      therapyHistory: '',
      medications: '',
      dailyRoutine: '',
      waterIntake: '',
      caffeineIntake: '',
      socialTime: '',
      mentalHealthGoals: ''
    };
    
    let loadedInfo;
    if (savedUserInfo) {
      loadedInfo = { ...defaultInfo, ...JSON.parse(savedUserInfo) };
    } else {
      loadedInfo = defaultInfo;
    }
    
    setUserInfo(loadedInfo);
    
    // Set height in feet/inches
    const { feet, inches } = inchesToFeetInches(loadedInfo.height);
    setHeightFeet(feet);
    setHeightInches(inches);
    
    // Calculate BMI
    const bmiValue = calculateBMI(loadedInfo.weight, loadedInfo.height);
    setBmi(bmiValue);
    setBmiCategory(getBMICategory(bmiValue));
  }, []);

  const stats = [
    { icon: <FaFire color="#e74c3c" />, value: '12', label: 'Day Streak' },
    { icon: <FaTrophy color="#f39c12" />, value: '8', label: 'Badges Earned' },
    { icon: <FaClock color="#3498db" />, value: '245', label: 'Focus Minutes' },
    { icon: <FaHeart color="#e84393" />, value: '156', label: 'Moods Logged' },
  ];

  // Scroll to section
  const scrollToSection = (sectionId) => {
    if (sectionRefs[sectionId]?.current) {
      const yOffset = -100;
      const y = sectionRefs[sectionId].current.getBoundingClientRect().top + window.pageYOffset + yOffset;
      window.scrollTo({ top: y, behavior: 'smooth' });
    }
  };

  // Start editing a section
  const startEditing = (section) => {
    setTempInfo({ ...userInfo });
    
    // Set temporary height values
    const { feet, inches } = inchesToFeetInches(userInfo.height);
    setTempHeightFeet(feet);
    setTempHeightInches(inches);
    
    setEditingSection(section);
    // Scroll to section after a small delay
    setTimeout(() => scrollToSection(section), 100);
  };

  // Save edited section
  const saveSection = () => {
    // If editing physical section, combine feet/inches to inches
    let updatedInfo = { ...tempInfo };
    if (editingSection === 'physical') {
      const totalInches = feetInchesToInches(tempHeightFeet, tempHeightInches);
      updatedInfo.height = totalInches;
    }
    
    setUserInfo(updatedInfo);
    localStorage.setItem('userInfo', JSON.stringify(updatedInfo));
    localStorage.setItem('userName', updatedInfo.name);
    
    // Update height display
    if (editingSection === 'physical') {
      const { feet, inches } = inchesToFeetInches(updatedInfo.height);
      setHeightFeet(feet);
      setHeightInches(inches);
      
      // Recalculate BMI
      const bmiValue = calculateBMI(updatedInfo.weight, updatedInfo.height);
      setBmi(bmiValue);
      setBmiCategory(getBMICategory(bmiValue));
    }
    
    setEditingSection(null);
  };

  // Cancel editing
  const cancelEditing = () => {
    setEditingSection(null);
  };

  // Handle field change
  const handleChange = (field, value) => {
    setTempInfo({ ...tempInfo, [field]: value });
    
    // If weight or height changes in edit mode, update BMI preview
    if (editingSection === 'physical') {
      let heightForBMI = tempInfo.height;
      if (field === 'height') {
        heightForBMI = value;
      } else if (field === 'weight') {
        const newWeight = value;
        const previewBMI = calculateBMI(newWeight, tempInfo.height);
        // Don't store, just for preview
      }
    }
  };

  // Handle height feet/inches change
  const handleHeightFeetChange = (feet) => {
    setTempHeightFeet(feet);
    const totalInches = feetInchesToInches(feet, tempHeightInches);
    handleChange('height', totalInches);
  };

  const handleHeightInchesChange = (inches) => {
    setTempHeightInches(inches);
    const totalInches = feetInchesToInches(tempHeightFeet, inches);
    handleChange('height', totalInches);
  };

  // Avatar handlers
  const handleUrlSubmit = () => {
    if (customImageUrl.trim()) {
      const newInfo = { ...userInfo, avatar: customImageUrl, avatarCategory: 'custom' };
      setUserInfo(newInfo);
      localStorage.setItem('userAvatar', customImageUrl);
      localStorage.setItem('userAvatarCategory', 'custom');
      localStorage.setItem('userInfo', JSON.stringify(newInfo));
      setShowAvatarPicker(false);
      setCustomImageUrl('');
      setShowUrlInput(false);
    }
  };

  const handleImageUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const imageData = reader.result;
        const newInfo = { ...userInfo, avatar: imageData, avatarCategory: 'uploaded' };
        setUserInfo(newInfo);
        localStorage.setItem('userAvatar', imageData);
        localStorage.setItem('userAvatarCategory', 'uploaded');
        localStorage.setItem('userInfo', JSON.stringify(newInfo));
        setShowAvatarPicker(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAvatarSelect = (avatarUrl, category) => {
    const newInfo = { ...userInfo, avatar: avatarUrl, avatarCategory: category };
    setUserInfo(newInfo);
    localStorage.setItem('userAvatar', avatarUrl);
    localStorage.setItem('userAvatarCategory', category);
    localStorage.setItem('userInfo', JSON.stringify(newInfo));
    setShowAvatarPicker(false);
    setSelectedCategory(null);
  };

  const handleLogout = () => {
    localStorage.removeItem('isLoggedIn');
    localStorage.removeItem('userName');
    localStorage.removeItem('userEmail');
    localStorage.removeItem('userAvatar');
    localStorage.removeItem('userAvatarCategory');
    localStorage.removeItem('userInfo');
    navigate('/');
  };

  // Render editable field
  const renderEditableField = (label, field, type = 'text', options = null) => {
    const isEditing = editingSection !== null;
    const value = isEditing ? tempInfo[field] : userInfo[field];
    
    if (isEditing) {
      if (options) {
        return (
          <select
            value={value || ''}
            onChange={(e) => handleChange(field, e.target.value)}
            style={styles.select}
          >
            <option value="">Select {label}</option>
            {options.map(opt => (
              <option key={opt} value={opt}>{opt}</option>
            ))}
          </select>
        );
      }
      if (type === 'textarea') {
        return (
          <textarea
            value={value || ''}
            onChange={(e) => handleChange(field, e.target.value)}
            placeholder={`Enter ${label}`}
            style={styles.textarea}
            rows="3"
          />
        );
      }
      if (field === 'weight') {
        return (
          <div>
            <input
              type="number"
              value={value || ''}
              onChange={(e) => handleChange(field, e.target.value)}
              placeholder="Weight in kg"
              style={styles.input}
              step="0.1"
            />
            <span style={styles.unitHint}>kg</span>
          </div>
        );
      }
      return (
        <input
          type={type}
          value={value || ''}
          onChange={(e) => handleChange(field, e.target.value)}
          placeholder={`Enter ${label}`}
          style={styles.input}
        />
      );
    }
    
    if (field === 'height') {
      const { feet, inches } = inchesToFeetInches(value);
      return <p style={styles.fieldValue}>{feet}'{inches}" ({value || 0} inches)</p>;
    }
    
    if (field === 'weight') {
      return <p style={styles.fieldValue}>{value ? `${value} kg` : 'Not provided'}</p>;
    }
    
    return <p style={styles.fieldValue}>{value || 'Not provided'}</p>;
  };

  // Section Component
  const EditableSection = ({ title, icon, sectionId, fields, refKey }) => {
    const isEditing = editingSection === sectionId;
    
    return (
      <div ref={sectionRefs[refKey]} style={styles.section}>
        <div style={styles.sectionHeader}>
          <h3 style={styles.sectionTitle}>{icon} {title}</h3>
          {!isEditing ? (
            <button onClick={() => startEditing(sectionId)} style={styles.editSectionBtn}>
              <FaEdit /> Edit
            </button>
          ) : (
            <div style={styles.sectionActions}>
              <button onClick={saveSection} style={styles.saveSectionBtn}>
                <FaCheckCircle /> Save
              </button>
              <button onClick={cancelEditing} style={styles.cancelSectionBtn}>
                <FaTimes /> Cancel
              </button>
            </div>
          )}
        </div>
        
        <div style={styles.formGrid}>
          {fields.map((field) => (
            <div key={field.field} style={styles.formField}>
              <label style={styles.label}>{field.icon} {field.label}</label>
              {renderEditableField(field.label, field.field, field.type || 'text', field.options)}
            </div>
          ))}
        </div>
      </div>
    );
  };

  const currentInfo = editingSection !== null ? tempInfo : userInfo;
  const previewBMI = editingSection === 'physical' ? calculateBMI(tempInfo.weight, tempInfo.height) : bmi;
  const previewBMICategory = editingSection === 'physical' ? getBMICategory(previewBMI) : bmiCategory;

  // Section configurations
  const personalFields = [
    { label: 'Full Name', field: 'name', icon: <FaUser size={12} /> },
    { label: 'Age', field: 'age', type: 'number', icon: <FaBirthdayCake size={12} /> },
    { label: 'Birthday', field: 'birthday', type: 'date', icon: <FaCalendar size={12} /> },
    { label: 'Gender', field: 'gender', type: 'select', options: ['Male', 'Female', 'Non-binary', 'Prefer not to say'], icon: <FaVenusMars size={12} /> },
  ];

  const physicalFields = [
    { label: 'Height', field: 'height', icon: <FaRuler size={12} /> },
    { label: 'Weight (kg)', field: 'weight', type: 'number', icon: <FaWeight size={12} /> },
  ];

  const mentalHealthFields = [
    { label: 'Primary Concern', field: 'primaryConcern', type: 'select', options: concerns, icon: <FaBrain size={12} /> },
    { label: 'Sleep Hours (per night)', field: 'sleepHours', type: 'number', icon: <FaMoon size={12} /> },
    { label: 'Exercise Frequency', field: 'exerciseFrequency', type: 'select', options: exerciseOptions, icon: <FaDumbbell size={12} /> },
    { label: 'Stress Level', field: 'stressLevel', type: 'select', options: stressLevels, icon: <FaSmile size={12} /> },
    { label: 'Mood Pattern', field: 'moodPattern', type: 'select', options: moodPatterns, icon: <FaBrain size={12} /> },
    { label: 'Therapy History', field: 'therapyHistory', type: 'textarea', icon: <FaUserMd size={12} /> },
    { label: 'Current Medications', field: 'medications', type: 'textarea', icon: <FaNotesMedical size={12} /> },
  ];

  const lifestyleFields = [
    { label: 'Daily Routine', field: 'dailyRoutine', type: 'textarea', icon: <FaCoffee size={12} /> },
    { label: 'Water Intake (glasses/day)', field: 'waterIntake', type: 'number', icon: <FaApple size={12} /> },
    { label: 'Caffeine Intake', field: 'caffeineIntake', icon: <FaCoffee size={12} /> },
    { label: 'Social Time (hours/week)', field: 'socialTime', type: 'number', icon: <FaUser size={12} /> },
  ];

  const goalsFields = [
    { label: 'Mental Health Goals', field: 'mentalHealthGoals', type: 'textarea', icon: <FaBrain size={12} /> },
  ];

  return (
    <div style={styles.container}>
      <Navbar />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>👤 Profile</h1>
          <p style={styles.subtitle}>Manage your personal and health information</p>
        </div>

        {/* Avatar Card */}
        <div style={styles.avatarCard}>
          <div style={styles.avatarContainer}>
            <div style={styles.avatarWrapper}>
              {currentInfo.avatar ? (
                <img src={currentInfo.avatar} alt="Avatar" style={styles.avatarImage} />
              ) : (
                <div style={styles.avatarPlaceholder}>
                  <FaUser size={50} color="#ccc" />
                </div>
              )}
              <button 
                style={styles.editAvatarBtn}
                onClick={() => setShowAvatarPicker(!showAvatarPicker)}
              >
                <FaCamera size={16} />
              </button>
            </div>
            <h2 style={styles.userName}>{currentInfo.name}</h2>
            <div style={styles.userInfo}>
              <div style={styles.infoRow}><FaEnvelope /> {currentInfo.email}</div>
              <div style={styles.infoRow}><FaCalendar /> Member since {currentInfo.joined}</div>
            </div>
          </div>

          {/* Avatar Picker Popup */}
          {showAvatarPicker && (
            <div style={styles.avatarPicker}>
              <div style={styles.pickerHeader}>
                <h4>Choose Your Avatar</h4>
                <button onClick={() => setShowAvatarPicker(false)} style={styles.closeBtn}>✕</button>
              </div>
              <div style={styles.uploadSection}>
                <label style={styles.uploadBtn}>
                  <FaUpload /> Upload Photo
                  <input type="file" accept="image/*" onChange={handleImageUpload} style={{ display: 'none' }} />
                </label>
                <button style={styles.urlBtn} onClick={() => setShowUrlInput(!showUrlInput)}>
                  <FaImage /> Use Image URL
                </button>
              </div>
              {showUrlInput && (
                <div style={styles.urlInputContainer}>
                  <input type="text" placeholder="Paste image URL here..." value={customImageUrl} onChange={(e) => setCustomImageUrl(e.target.value)} style={styles.urlInput} />
                  <button onClick={handleUrlSubmit} style={styles.urlSubmitBtn}>Add</button>
                </div>
              )}
              {!selectedCategory ? (
                <>
                  <div style={styles.categoryGrid}>
                    <div style={styles.categoryCard} onClick={() => setSelectedCategory('boys')}>
                      <div style={styles.categoryIcon}><FaMars size={40} color="#3498db" /></div>
                      <h4>Boys</h4>
                    </div>
                    <div style={styles.categoryCard} onClick={() => setSelectedCategory('girls')}>
                      <div style={styles.categoryIcon}><FaVenus size={40} color="#e84393" /></div>
                      <h4>Girls</h4>
                    </div>
                  </div>
                  <div style={styles.customSection}>
                    <h4 style={styles.customTitle}>🎨 More Avatars</h4>
                    <div style={styles.avatarGrid}>
                      {customAvatars.map((avatar) => (
                        <div key={avatar.id} style={styles.avatarOption} onClick={() => handleAvatarSelect(avatar.url, avatar.category)}>
                          <img src={avatar.url} alt={avatar.name} style={styles.avatarOptionImage} />
                        </div>
                      ))}
                    </div>
                  </div>
                </>
              ) : (
                <>
                  <button onClick={() => setSelectedCategory(null)} style={styles.backBtn}>← Back</button>
                  <div style={styles.avatarGrid}>
                    {(selectedCategory === 'boys' ? boyAvatars : girlAvatars).map((avatar) => (
                      <div key={avatar.id} style={styles.avatarOption} onClick={() => handleAvatarSelect(avatar.url, selectedCategory)}>
                        <img src={avatar.url} alt={avatar.name} style={styles.avatarOptionImage} />
                      </div>
                    ))}
                  </div>
                </>
              )}
              {currentInfo.avatar && (
                <button onClick={() => {
                  const newInfo = { ...currentInfo, avatar: null, avatarCategory: null };
                  setUserInfo(newInfo);
                  localStorage.removeItem('userAvatar');
                  localStorage.removeItem('userAvatarCategory');
                  localStorage.setItem('userInfo', JSON.stringify(newInfo));
                  setShowAvatarPicker(false);
                }} style={styles.removeBtn}>
                  <FaTrash /> Remove Avatar
                </button>
              )}
            </div>
          )}
        </div>

        {/* Custom Height Input Section (when editing physical) */}
        {editingSection === 'physical' && (
          <div style={styles.heightInputCard}>
            <div style={styles.heightInputContainer}>
              <label style={styles.label}><FaRuler /> Height (Feet & Inches)</label>
              <div style={styles.heightInputGroup}>
                <input
                  type="number"
                  value={tempHeightFeet}
                  onChange={(e) => handleHeightFeetChange(e.target.value)}
                  placeholder="Feet"
                  style={styles.heightInput}
                />
                <span style={styles.heightSeparator}>ft</span>
                <input
                  type="number"
                  value={tempHeightInches}
                  onChange={(e) => handleHeightInchesChange(e.target.value)}
                  placeholder="Inches"
                  style={styles.heightInput}
                  min="0"
                  max="11"
                />
                <span style={styles.heightSeparator}>in</span>
              </div>
            </div>
          </div>
        )}

        {/* BMI Display Card */}
        <div style={styles.bmiCard}>
          <div style={styles.bmiHeader}>
            <FaCalculator size={24} color="#667eea" />
            <h3 style={styles.bmiTitle}>Body Mass Index (BMI)</h3>
          </div>
          <div style={styles.bmiContent}>
            <div style={styles.bmiValue}>
              <span style={{ fontSize: '48px', fontWeight: 'bold', color: getBMIColor(previewBMI) }}>
                {previewBMI || '—'}
              </span>
              {previewBMI && <span style={styles.bmiUnit}>kg/m²</span>}
            </div>
            {previewBMI && (
              <div style={{ ...styles.bmiCategory, backgroundColor: `${getBMIColor(previewBMI)}20`, color: getBMIColor(previewBMI) }}>
                {previewBMICategory}
              </div>
            )}
            <div style={styles.bmiInfo}>
              <small>
                <FaInfoCircle /> BMI = weight(kg) ÷ height(m)²
                <br />
                Normal range: 18.5 - 24.9
              </small>
            </div>
          </div>
          {/* BMI Scale Bar */}
          <div style={styles.bmiScale}>
            <div style={{ ...styles.bmiScaleSegment, background: '#3498db', width: '20%' }}>Underweight</div>
            <div style={{ ...styles.bmiScaleSegment, background: '#2ecc71', width: '30%' }}>Normal</div>
            <div style={{ ...styles.bmiScaleSegment, background: '#f39c12', width: '25%' }}>Overweight</div>
            <div style={{ ...styles.bmiScaleSegment, background: '#e74c3c', width: '25%' }}>Obese</div>
          </div>
          {previewBMI && (
            <div style={{ ...styles.bmiIndicator, left: `${Math.min(Math.max((previewBMI / 40) * 100, 0), 100)}%` }}>
              <FaArrowUp size={12} />
            </div>
          )}
        </div>

        {/* Editable Sections */}
        <EditableSection 
          title="Personal Information" 
          icon={<FaUser />} 
          sectionId="personal" 
          fields={personalFields}
          refKey="personal"
        />

        <EditableSection 
          title="Physical Information" 
          icon={<FaRuler />} 
          sectionId="physical" 
          fields={physicalFields}
          refKey="physical"
        />

        <EditableSection 
          title="Mental Health Information" 
          icon={<FaBrain />} 
          sectionId="mental" 
          fields={mentalHealthFields}
          refKey="mental"
        />

        <EditableSection 
          title="Lifestyle Information" 
          icon={<FaCoffee />} 
          sectionId="lifestyle" 
          fields={lifestyleFields}
          refKey="lifestyle"
        />

        <EditableSection 
          title="Mental Health Goals" 
          icon={<FaHeart />} 
          sectionId="goals" 
          fields={goalsFields}
          refKey="goals"
        />

        {/* Stats Grid */}
        <div style={styles.statsGrid}>
          {stats.map((stat, index) => (
            <div key={index} style={styles.statCard}>
              <div style={styles.statIcon}>{stat.icon}</div>
              <div style={styles.statValue}>{stat.value}</div>
              <div style={styles.statLabel}>{stat.label}</div>
            </div>
          ))}
        </div>

        {/* Logout Button */}
        <div style={styles.menuCard}>
          <button onClick={handleLogout} style={styles.logoutBtn}>
            <FaSignOutAlt /> Logout
          </button>
        </div>
      </div>
    </div>
  );
}

